function pareto(items, keyFn) {
  const map = new Map();
  for (const item of items) {
    const key = keyFn(item);
    if (!map.has(key)) map.set(key, { key, count: 0, refund: 0 });
    const e = map.get(key);
    e.count++; e.refund += item.refund_amount || 0;
  }
  const arr = [...map.values()].sort((a, b) => b.count - a.count || b.refund - a.refund || a.key.localeCompare(b.key));
  const total = arr.reduce((s, e) => s + e.count, 0);
  let cum = 0;
  for (const e of arr) {
    e.share = total ? e.count / total : 0;
    cum += e.count;
    e.cumulativeShare = total ? cum / total : 0;
  }
  return arr;
}

function analyse(orders, returns) {
  const bySku = pareto(returns, r => r.sku);
  const byReason = pareto(returns, r => r.bucket);
  const bySkuReason = pareto(returns, r => `${r.sku} x ${r.bucket}`);

  const orderById = new Map();
  for (const o of orders) if (!orderById.has(o.order_id)) orderById.set(o.order_id, o);
  const enriched = returns.map(r => ({ ...r, region: (orderById.get(r.order_id) || {}).region || "unknown" }));
  const byRegion = pareto(enriched, r => r.region);

  const customerOrders = new Map();
  for (const o of orders) {
    if (!o.customer_id) continue;
    if (!customerOrders.has(o.customer_id)) customerOrders.set(o.customer_id, new Set());
    customerOrders.get(o.customer_id).add(o.order_id);
  }
  const customerReturns = new Map();
  for (const r of returns) {
    const order = orderById.get(r.order_id);
    const cust = order ? order.customer_id : "";
    if (!cust) continue;
    customerReturns.set(cust, (customerReturns.get(cust) || 0) + 1);
  }
  const repeatReturners = [];
  for (const [customer, orderSet] of customerOrders) {
    const ret = customerReturns.get(customer) || 0;
    if (ret === 0) continue;
    repeatReturners.push({ customer, orders: orderSet.size, returns: ret, returnRate: ret / orderSet.size });
  }
  repeatReturners.sort((a, b) => b.returns - a.returns || b.returnRate - a.returnRate);

  const returnsByOrder = new Map();
  for (const r of returns) {
    if (!returnsByOrder.has(r.order_id)) returnsByOrder.set(r.order_id, []);
    returnsByOrder.get(r.order_id).push(r);
  }
  const doubleRefunds = [];
  for (const [orderId, list] of returnsByOrder) {
    const hasReturn = list.some(r => !r.isChargebackRow);
    const hasChargeback = list.some(r => r.chargeback || r.isChargebackRow);
    const flagged = list.some(r => r.chargeback);
    if ((hasReturn && hasChargeback) || (list.length > 1 && flagged)) {
      doubleRefunds.push({ order_id: orderId, sku: list.map(r => r.sku).join("; "), detail: `Order has ${list.length} refund rows including a chargeback marker` });
    }
  }
  doubleRefunds.sort((a, b) => a.order_id.localeCompare(b.order_id));

  const totalRefund = returns.reduce((s, r) => s + r.refund_amount, 0);
  return { bySku, byReason, bySkuReason, byRegion, repeatReturners, repeatOnly: repeatReturners.filter(r => r.returns >= 2), doubleRefunds, totalReturns: returns.length, totalOrders: new Set(orders.map(o => o.order_id)).size, totalRefund, enriched };
}

function paretoToCsv(bySku) {
  const lines = ["sku,returns,refund_amount,share_pct,cumulative_share_pct"];
  for (const e of bySku) lines.push([e.key, e.count, e.refund.toFixed(2), (e.share * 100).toFixed(1), (e.cumulativeShare * 100).toFixed(1)].join(","));
  return lines.join("\n") + "\n";
}

function table(lines, title, rows, cols) {
  lines.push(`## ${title}`, "");
  if (!rows.length) { lines.push("None.", ""); return; }
  lines.push(`| ${cols.map(c => c[0]).join(" | ")} |`, `| ${cols.map(() => "---").join(" | ")} |`);
  for (const r of rows) lines.push(`| ${cols.map(c => c[1](r)).join(" | ")} |`);
  lines.push("");
}

const pct = v => `${(v * 100).toFixed(1)}%`;
const money = v => v.toFixed(2);

function buildReport(analysis) {
  const lines = [];
  lines.push("# Returns Pareto Report", "");
  lines.push(`Orders: ${analysis.totalOrders}`);
  lines.push(`Returns: ${analysis.totalReturns}`);
  lines.push(`Total refund amount: ${money(analysis.totalRefund)}`);
  lines.push(`Overall return rate by order count: ${analysis.totalOrders ? pct(analysis.totalReturns / analysis.totalOrders) : "0.0%"}`, "");
  lines.push("Read the cumulative share columns top down. The rows that push cumulative share to about 80 percent are usually the small set of drivers worth fixing first.", "");
  table(lines, "Pareto by SKU", analysis.bySku, [["SKU", r => r.key], ["Returns", r => String(r.count)], ["Refund amount", r => money(r.refund)], ["Share", r => pct(r.share)], ["Cumulative share", r => pct(r.cumulativeShare)]]);
  table(lines, "Pareto by reason", analysis.byReason, [["Reason bucket", r => r.key], ["Returns", r => String(r.count)], ["Refund amount", r => money(r.refund)], ["Share", r => pct(r.share)], ["Cumulative share", r => pct(r.cumulativeShare)]]);
  table(lines, "Pareto by SKU x reason", analysis.bySkuReason, [["SKU x reason", r => r.key], ["Returns", r => String(r.count)], ["Refund amount", r => money(r.refund)], ["Share", r => pct(r.share)], ["Cumulative share", r => pct(r.cumulativeShare)]]);
  table(lines, "Pareto by region", analysis.byRegion, [["Region", r => r.key], ["Returns", r => String(r.count)], ["Refund amount", r => money(r.refund)], ["Share", r => pct(r.share)], ["Cumulative share", r => pct(r.cumulativeShare)]]);
  table(lines, "Repeat returners", analysis.repeatReturners, [["Customer", r => r.customer], ["Orders", r => String(r.orders)], ["Returns", r => String(r.returns)], ["Return rate", r => pct(r.returnRate)]]);
  lines.push("## Double-refund flags", "");
  if (!analysis.doubleRefunds.length) lines.push("None.", "");
  else { for (const d of analysis.doubleRefunds) lines.push(`- ${d.order_id} (${d.sku}): ${d.detail}`); lines.push(""); }
  lines.push("## What to fix first", "");
  if (analysis.bySku.length) lines.push(`- Top SKU: ${analysis.bySku[0].key} accounts for ${pct(analysis.bySku[0].share)} of returns.`);
  if (analysis.byReason.length) lines.push(`- Top reason bucket: ${analysis.byReason[0].key} accounts for ${pct(analysis.byReason[0].share)} of returns.`);
  if (analysis.bySkuReason.length) lines.push(`- Top SKU x reason pair: ${analysis.bySkuReason[0].key} with ${analysis.bySkuReason[0].count} returns.`);
  lines.push(`- Repeat returners with 2 or more returns: ${analysis.repeatOnly.length}.`);
  lines.push(`- Double-refund flags to review manually: ${analysis.doubleRefunds.length}.`);
  lines.push("");
  return lines.join("\n");
}

window.ReturnsPareto = { parseCsv: parseCsv, loadReasonMap: loadReasonMap, bucketReason: bucketReason, isTruthyFlag: isTruthyFlag, normaliseOrders: normaliseOrders, normaliseReturns: normaliseReturns, loadOrders: loadOrders, loadReturns: loadReturns, analyse: analyse, paretoToCsv: paretoToCsv, buildReport: buildReport };
